{
  Ciphertext x("x");
  Ciphertext X1 = x * coeff(3, 1);
  Ciphertext X3 = x * coeff(3, 3);
  Ciphertext X5 = x * coeff(3, 5);
  Ciphertext X7 = x * coeff(3, 7);
